import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.G0y0PQA7.js";const l="/relio/shots/ko/canvas-palette.png",o="/relio/shots/ko/canvas-arrange-menu.png",i="/relio/shots/ko/canvas-outline-marks.png",f=JSON.parse('{"title":"캔버스와 팔레트","description":"","frontmatter":{},"headers":[],"relativePath":"features/canvas.md","filePath":"features/canvas.md"}'),b={name:"features/canvas.md"};function n(s,t,h,k,c,u){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="캔버스와-팔레트" tabindex="-1">캔버스와 팔레트 <a class="header-anchor" href="#캔버스와-팔레트" aria-label="Permalink to &quot;캔버스와 팔레트&quot;">​</a></h1><p>캔버스 읽는 법, 팔레트 도구, 선택·옮기기, 배치 메뉴, 보기 메뉴의 표시 설정, 확대·이동과 패널, 아웃라인을 설명합니다.</p><p>화면을 빠르게 다루는 방법만 보려면 빠른 시작의 <a href="/relio/quick/navigate">화면 다루기</a>를, 그리는 순서는 <a href="/relio/quick/draw">테이블·컬럼·관계 그리기</a>를 보세요.</p><p>화면의 각 부분(메뉴·도구 모음·팔레트·아웃라인·상태 표시줄)과 &quot;노드&quot;라는 말은 <a href="/relio/features/#화면-구성">기능 설명 › 화면 구성</a>에 정리해 두었습니다.</p><h2 id="캔버스-읽는-법" tabindex="-1">캔버스 읽는 법 <a class="header-anchor" href="#캔버스-읽는-법" aria-label="Permalink to &quot;캔버스 읽는 법&quot;">​</a></h2><h3 id="테이블-상자" tabindex="-1">테이블 상자 <a class="header-anchor" href="#테이블-상자" aria-label="Permalink to &quot;테이블 상자&quot;">​</a></h3><ul><li>머리에 테이블 이름이 있고, 아래에 컬럼이 한 줄씩 나옵니다. 기본 키(PK) 컬럼은 위쪽에 따로 모이고 가는 선으로 나머지와 나뉩니다.</li><li>컬럼 줄 왼쪽의 <strong>PK</strong> · <strong>FK</strong> 딱지는 기본 키(PK) · 외래 키(FK) 컬럼입니다. 둘 다이면 딱지가 둘 붙습니다.</li><li>이름 오른쪽에 형식(예: <code>varchar(100)</code>)이, 줄 끝에 작은 글자로 <strong>NN</strong>(NOT NULL) · <strong>UQ</strong>(UNIQUE)가 나옵니다.</li><li>자동 증가(AUTO_INCREMENT) 컬럼은 이름 바로 뒤에 작은 원 안의 + 표시가 붙습니다. 마우스를 올리면 &quot;자동 증가&quot;가 보입니다.</li><li>그룹 컬럼은 <code>≡ 그룹명</code> 한 줄로 기울여 나옵니다. 보기 › 표기 수준 ▸ › <strong>그룹 확장</strong>을 켜면 그룹 안 컬럼을 펼쳐 보입니다.</li><li>뷰는 테이블과 같은 모양이고 머리 오른쪽에 <code>VIEW</code>가 붙습니다.</li><li>컬럼이 하나도 없는 테이블에는 &quot;더블클릭해 컬럼 추가&quot; 안내가 흐리게 보입니다(그림 내보내기·인쇄에는 나오지 않음).</li><li>빈 새 문서에는 캔버스 가운데에 &quot;테이블 추가 (T)&quot;와 첫 테이블을 만드는 방법이 흐리게 보이고, 노드를 하나 만들면 사라집니다.</li></ul><h3 id="표기-수준" tabindex="-1">표기 수준 <a class="header-anchor" href="#표기-수준" aria-label="Permalink to &quot;표기 수준&quot;">​</a></h3><p>보기 › 표기 수준 ▸에서 테이블 상자에 무엇을 보일지 고릅니다.</p><table tabindex="0"><thead><tr><th>표기 수준</th><th>보이는 것</th></tr></thead><tbody><tr><td>자세히</td><td>모든 컬럼과 PK·FK 딱지, 형식, NN·UQ, 자동 증가 표시</td></tr><tr><td>테이블명만</td><td>테이블 이름만(컬럼 없음)</td></tr><tr><td>컬럼명</td><td>모든 컬럼의 이름만</td></tr><tr><td>키만</td><td>PK·FK 컬럼과 다른 테이블이 참조하는 컬럼만, 딱지·형식·NN·UQ와 함께</td></tr><tr><td>자세히(형식 없음)</td><td>자세히에서 형식만 뺀 것</td></tr><tr><td>컬럼명과 키</td><td>모든 컬럼의 이름과 PK·FK 딱지</td></tr></tbody></table><h3 id="관계선-끝-기호" tabindex="-1">관계선 끝 기호 <a class="header-anchor" href="#관계선-끝-기호" aria-label="Permalink to &quot;관계선 끝 기호&quot;">​</a></h3><p>관계선은 부모(참조되는 테이블)와 자식(외래 키(FK)를 가진 테이블)을 잇습니다. 선 끝 기호는 관계 정보 창의 <strong>다중성</strong>을 보여 주고, 보기 › 표기법 ▸에서 IE·IDEF1X 중 고릅니다. 노트 연결선은 기호 없는 점선입니다.</p><table tabindex="0"><thead><tr><th>다중성</th><th>IE</th><th>IDEF1X</th></tr></thead><tbody><tr><td>1(부모 기본값·자식 1)</td><td>짧은 막대 하나</td><td>짧은 막대 하나</td></tr><tr><td>0..1</td><td>막대 + 빈 원</td><td>부모 쪽: 막대 + 빈 원, 자식 쪽: 채운 점 + <code>Z</code></td></tr><tr><td>1..n(자식 기본값)</td><td>까마귀발 + 막대</td><td>채운 점 + <code>P</code></td></tr><tr><td>0..n</td><td>까마귀발 + 빈 원</td><td>채운 점</td></tr></tbody></table><h2 id="팔레트-도구" tabindex="-1">팔레트 도구 <a class="header-anchor" href="#팔레트-도구" aria-label="Permalink to &quot;팔레트 도구&quot;">​</a></h2><table tabindex="0"><thead><tr><th>도구</th><th>키</th><th>쓰는 법</th></tr></thead><tbody><tr><td>선택</td><td><kbd>V</kbd></td><td>클릭으로 선택, 끌어서 옮기기, 빈 곳을 끌어 여러 개 선택.</td></tr><tr><td>손 도구</td><td><kbd>H</kbd></td><td>캔버스 어디를 끌어도 화면만 움직입니다. 쓴 뒤에도 켜져 있고 <kbd>Esc</kbd>나 <kbd>V</kbd>로 끝냅니다(1.0.2부터).</td></tr><tr><td>테이블</td><td><kbd>T</kbd></td><td>누른 자리에 새 테이블을 만듭니다.</td></tr><tr><td>뷰</td><td><kbd>W</kbd></td><td>누른 자리에 새 뷰를 만듭니다.</td></tr><tr><td>1:N 관계(일대다)</td><td><kbd>R</kbd></td><td>부모 → 자식. 자식에 부모 기본 키(PK)를 따르는 FK 컬럼이 생깁니다.</td></tr><tr><td>기존 컬럼을 사용한 1:N 관계</td><td></td><td>부모 → 자식. 자식의 기존 컬럼을 FK로 지정하는 창이 열립니다.</td></tr><tr><td>N:M 관계(다대다)</td><td></td><td>두 테이블을 누르면 가운데에 교차 테이블을 만들고 1:N 관계 두 개로 잇습니다.</td></tr><tr><td>재귀 관계(자기 참조)</td><td></td><td>테이블 하나를 누르면 자기 자신을 참조하는 관계와 FK 컬럼이 생깁니다.</td></tr><tr><td>노트</td><td><kbd>N</kbd></td><td>누른 자리에 노트를 만들고 바로 글을 칩니다.</td></tr><tr><td>노트 연결(점선)</td><td></td><td>노트 → 대상 노드를 누르면 점선으로 잇습니다.</td></tr><tr><td>카테고리</td><td><kbd>C</kbd></td><td>끌어서 영역을 만듭니다. 영역 안의 노드가 그 카테고리에 속합니다.</td></tr><tr><td>이미지 삽입</td><td></td><td>그림 파일(bmp·jpg·jpeg·gif·png)을 골라 넣습니다. 그림은 파일 안에 들어가므로 큰 그림은 파일을 크게 만듭니다.</td></tr></tbody></table><ul><li>도구는 한 번 쓰면 선택 도구로 돌아갑니다. <kbd>Shift</kbd>를 누른 채 쓰면 같은 도구가 유지되어 여러 개를 이어 만들 수 있습니다. 손 도구는 늘 유지됩니다.</li><li>관계 도구는 첫 테이블을 누른 뒤 두 번째 테이블을 누르거나, 첫 테이블에서 끌어 두 번째 테이블에서 놓습니다. 빈 곳을 누르거나 <kbd>Esc</kbd>를 누르면 취소합니다. 1:N 관계 도구로 같은 테이블을 두 번 누르면 재귀 관계가 됩니다.</li><li><strong>키보드로만 관계 만들기</strong> — <kbd>Tab</kbd>으로 부모 테이블에 포커스를 옮기고 <kbd>R</kbd>로 관계 도구를 고른 뒤 <kbd>Enter</kbd>로 부모를 정합니다. 다시 <kbd>Tab</kbd>으로 자식 테이블에 포커스를 옮기고 <kbd>Enter</kbd>를 누르면 관계가 생깁니다.</li><li>부모에 기본 키가 없으면 &quot;참조할 컬럼이 없습니다 — 부모 테이블에 기본 키가 없습니다.&quot;라고 알립니다.</li><li>새 테이블의 이름은 앱 언어를 따릅니다(한국어면 논리명 &quot;새 테이블&quot;, 물리명 <code>NEW_TABLE</code>).</li></ul><figure class="shot" data-scene="canvas-palette"><img src="'+l+'" alt="팔레트 — 선택·손·테이블·뷰·관계 4종·노트·노트 연결·카테고리·이미지 삽입" loading="lazy"><figcaption>팔레트 — 선택·손·테이블·뷰·관계 4종·노트·노트 연결·카테고리·이미지 삽입</figcaption></figure><h2 id="선택·옮기기" tabindex="-1">선택·옮기기 <a class="header-anchor" href="#선택·옮기기" aria-label="Permalink to &quot;선택·옮기기&quot;">​</a></h2><ul><li><strong>선택</strong> — 클릭, <kbd>Shift</kbd>+클릭(또는 <kbd>Ctrl</kbd>+클릭)으로 더하거나 빼기, 빈 곳을 끌어 범위 선택. <kbd>Esc</kbd>로 선택을 해제합니다.</li><li><strong>옮기기</strong> — 끌거나 방향키로 1칸, <kbd>Shift</kbd>+방향키로 10칸 옮깁니다. 끄는 동안 다른 노드의 경계·가운데에 맞춤 안내선이 보입니다.</li><li><strong>크기</strong> — 테이블·뷰를 고르면 왼쪽·오른쪽 손잡이로 너비를 바꿉니다. 넓히기는 마음대로, 줄이기는 내용이 다 보이는 너비까지입니다. 높이는 늘 컬럼 수에 맞습니다. 노트·이미지·카테고리는 손잡이로 크기를 바꿉니다.</li><li><strong>이름 바로 고치기</strong> — <kbd>F2</kbd>. 테이블은 물리명, 노트는 글을 그 자리에서 고칩니다. 다른 프로그램으로 넘어갔다 와도 칸이 닫히지 않고 이어 칠 수 있습니다.</li><li><strong>정보 창</strong> — 더블클릭 또는 <kbd>Enter</kbd>. <a href="/relio/features/dialogs">정보 창</a></li><li><strong>포커스 옮기기</strong> — <kbd>Tab</kbd> / <kbd>Shift</kbd>+<kbd>Tab</kbd>으로 다음·이전 노드.</li></ul><h3 id="더블클릭하면-열리는-것" tabindex="-1">더블클릭하면 열리는 것 <a class="header-anchor" href="#더블클릭하면-열리는-것" aria-label="Permalink to &quot;더블클릭하면 열리는 것&quot;">​</a></h3><table tabindex="0"><thead><tr><th>대상</th><th>열리는 것</th></tr></thead><tbody><tr><td>테이블</td><td>테이블 정보 창(컬럼 줄을 더블클릭하면 그 컬럼을 고른 채로)</td></tr><tr><td>뷰</td><td>뷰 정보 창</td></tr><tr><td>관계선</td><td>관계 정보 창</td></tr><tr><td>노트</td><td>그 자리에서 글 고치기(바깥을 누르면 확정)</td></tr><tr><td>노트 연결선</td><td>연결 정보 창(선 색)</td></tr><tr><td>스탬프</td><td>모델 특성 창 — <a href="/relio/features/model#모델-특성">모델 메뉴 › 모델 특성</a></td></tr><tr><td>이미지</td><td>이미지 정보 창</td></tr><tr><td>카테고리 영역</td><td>카테고리 이름 바로 고치기</td></tr></tbody></table><h3 id="캔버스에서-컬럼-다루기" tabindex="-1">캔버스에서 컬럼 다루기 <a class="header-anchor" href="#캔버스에서-컬럼-다루기" aria-label="Permalink to &quot;캔버스에서 컬럼 다루기&quot;">​</a></h3><ul><li>테이블 안 컬럼을 누르면 그 컬럼을 고릅니다. 보기 › <strong>컬럼 클릭 금지</strong>를 켜면 테이블만 골라집니다.</li><li>고른 컬럼을 끌어 같은 테이블 안에서 순서를 바꾸고, 다른 테이블에 놓으면 그리로 옮깁니다. <kbd>Ctrl</kbd>을 누른 채 놓으면 옮기지 않고 복사합니다.</li><li>다른 테이블이 참조하는 컬럼은 옮길 수 없습니다. FK 컬럼을 다른 테이블로 옮기면 관계를 다시 만들어 그 테이블이 자식이 됩니다.</li><li>그룹 컬럼은 그룹 단위로 옮기고, 그룹을 고르고 <kbd>Delete</kbd>를 누르면 테이블에서 그룹을 뺍니다.</li><li>아웃라인의 단어·그룹을 캔버스의 테이블에 끌어다 놓으면 컬럼(그룹)이 됩니다.</li></ul><h3 id="연결선" tabindex="-1">연결선 <a class="header-anchor" href="#연결선" aria-label="Permalink to &quot;연결선&quot;">​</a></h3><ul><li>관계선을 끌면 꺾임점이 생기고, 꺾임점을 끌어 옮기고, 꺾임점을 더블클릭하면 지웁니다.</li><li>관계선 끝을 끌어 같은 테이블 테두리의 다른 자리로 옮깁니다. 테이블 가운데쪽에 놓으면 자동 위치로 돌아갑니다.</li><li>관계 이름은 선 위에 그리지 않습니다. 관계선을 고르면 이름이 도구 설명으로 보입니다.</li></ul><h2 id="배치-메뉴" tabindex="-1">배치 메뉴 <a class="header-anchor" href="#배치-메뉴" aria-label="Permalink to &quot;배치 메뉴&quot;">​</a></h2><table tabindex="0"><thead><tr><th>메뉴 › 항목</th><th>쓸 수 있을 때</th><th>하는 일</th></tr></thead><tbody><tr><td>배치 › 왼쪽 맞춤 · 가운데 맞춤 · 오른쪽 맞춤</td><td>노드 2개 이상</td><td><strong>마지막에 고른</strong> 노드에 왼쪽·가운데·오른쪽을 맞춥니다.</td></tr><tr><td>배치 › 위 맞춤 · 가운데(세로) 맞춤 · 아래 맞춤</td><td>노드 2개 이상</td><td>마지막에 고른 노드에 위·가운데·아래를 맞춥니다.</td></tr><tr><td>배치 › 너비 맞춤 · 높이 맞춤</td><td>노드 2개 이상</td><td><strong>처음 고른</strong> 노드와 너비·높이를 같게 합니다. 테이블·뷰의 높이는 늘 내용에 맞으므로 높이 맞춤으로 바뀌지 않습니다.</td></tr><tr><td>배치 › 가로 정렬 · 세로 정렬</td><td>테이블·노트 3개 이상</td><td>양 끝 노드 사이에 나머지를 같은 간격으로 놓습니다.</td></tr><tr><td>배치 › 크기 자동 조정</td><td>테이블·뷰·노트</td><td>내용에 맞는 크기로 되돌립니다.</td></tr><tr><td>배치 › 직각 연결선</td><td>연결선</td><td>수평·수직 선으로 경로를 다시 그립니다.</td></tr><tr><td>배치 › 기본값 복원</td><td>연결선, 또는 연결선이 나가는 노드</td><td>꺾임점을 지우고 양 끝점을 자동 위치로 되돌립니다. 노드를 고르면 그 노드에서 나가는 선(노트에서 나가는 노트 연결선 포함, 자기 참조 관계 제외)에 씁니다.</td></tr><tr><td>배치 › 연결선 정리</td><td>연결선, 또는 연결선이 붙은 테이블</td><td>고른 선과 고른 노드에 붙은 선 전부의 꺾임점·끝점을 정리합니다.</td></tr><tr><td>배치 › 배경색</td><td>노드 또는 연결선</td><td>지금 색을 선택한 것에 칠합니다. 메뉴 이름 옆에 지금 색이 <code>(#1E90FF)</code>처럼 보입니다. 도구 모음의 배경색 ▼로 색을 고르면 그 색이 지금 색이 됩니다.</td></tr><tr><td>배치 › 글꼴 ▸ · 글꼴 크기 ▸</td><td>노드</td><td>고른 노드의 글꼴과 크기를 바꿉니다.</td></tr></tbody></table><p>맞춤 기준이 되는 노드는 선택 표시가 진하게 보입니다. 도구 모음의 **맞춤 ▾**는 본체를 누르면 마지막에 쓴 맞춤을 다시 하고, ▾를 누르면 맞춤 6종·너비/높이 맞춤·가로/세로 정렬을 고릅니다. 바꿀 것이 없을 때(이미 정리된 선 등)는 상태 표시줄에 안내만 나오고 문서는 바뀌지 않습니다.</p><figure class="shot" data-scene="canvas-arrange-menu"><img src="'+o+'" alt="배치 메뉴 — 테이블 세 개를 고르고 맞춤·정렬 항목을 연 모습" loading="lazy"><figcaption>배치 메뉴 — 테이블 세 개를 고르고 맞춤·정렬 항목을 연 모습</figcaption></figure><h2 id="보기-메뉴" tabindex="-1">보기 메뉴 <a class="header-anchor" href="#보기-메뉴" aria-label="Permalink to &quot;보기 메뉴&quot;">​</a></h2><h3 id="문서에-저장되는-표시-설정" tabindex="-1">문서에 저장되는 표시 설정 <a class="header-anchor" href="#문서에-저장되는-표시-설정" aria-label="Permalink to &quot;문서에 저장되는 표시 설정&quot;">​</a></h3><p>아래 설정은 <code>.erm</code> 문서에 저장되고, 바꾸면 문서가 &quot;변경됨&quot;이 되며 되돌릴 수 있습니다. 캔버스 오른쪽 클릭 › 문서 ▸ › 표시 ▸에도 같은 항목이 있습니다.</p><table tabindex="0"><thead><tr><th>메뉴 › 항목</th><th>고를 수 있는 값</th></tr></thead><tbody><tr><td>보기 › 뷰 모드 ▸</td><td>논리명 · 물리명 · 논리명/물리명 — 노드에 어느 이름을 보일지</td></tr><tr><td>보기 › 표기법 ▸</td><td>IE · IDEF1X — 관계선 끝 기호</td></tr><tr><td>보기 › 표기 수준 ▸</td><td>자세히 · 테이블명만 · 컬럼명 · 키만 · 자세히(형식 없음) · 컬럼명과 키, 그리고 <strong>그룹 확장</strong></td></tr><tr><td>보기 › 디자인 ▸</td><td>funny — 둥근 카드 · frame — 이중 테두리 · simple — 선</td></tr><tr><td>보기 › 대문자로 표시</td><td>이름을 대문자로 보입니다.</td></tr><tr><td>보기 › 스탬프 표시</td><td>캔버스 왼쪽 위에 모델 특성 표(프로젝트명·모델명·버전 등)를 보입니다.</td></tr><tr><td>보기 › 곡선 연결선</td><td>관계선을 곡선으로 그립니다.</td></tr></tbody></table><p>논리명과 물리명이 같으면 두 번 쓰지 않고 하나로 그립니다.</p><h3 id="이-pc에-기억되는-보기-설정" tabindex="-1">이 PC에 기억되는 보기 설정 <a class="header-anchor" href="#이-pc에-기억되는-보기-설정" aria-label="Permalink to &quot;이 PC에 기억되는 보기 설정&quot;">​</a></h3><table tabindex="0"><thead><tr><th>메뉴 › 항목</th><th>단축키</th><th>하는 일</th></tr></thead><tbody><tr><td>보기 › 설계 검사 표시</td><td></td><td>캔버스의 검사 표시를 켜고 끕니다. <a href="/relio/features/check">설계 검사와 추천</a></td></tr><tr><td>보기 › 참고도 캔버스에 표시</td><td></td><td>참고 지적도 캔버스에 그립니다.</td></tr><tr><td>보기 › 확대 · 축소 · 100%</td><td><kbd>Ctrl</kbd>+<kbd>=</kbd> · <kbd>Ctrl</kbd>+<kbd>-</kbd> · <kbd>Ctrl</kbd>+<kbd>0</kbd></td><td>배율을 바꿉니다.</td></tr><tr><td>보기 › 전체 맞춤 · 높이 맞춤 · 너비 맞춤</td><td></td><td>그림 전체(또는 높이·너비)가 화면에 들어오게 합니다.</td></tr><tr><td>보기 › 격자 · 격자에 맞추기</td><td></td><td>격자를 보이고, 노드를 격자에 맞춰 놓습니다(기본 둘 다 켬).</td></tr><tr><td>보기 › 관계 그리기 이름표</td><td></td><td>관계를 그리는 중 마우스가 올라간 테이블 위에 이름표를 띄웁니다.</td></tr><tr><td>보기 › 컬럼 클릭 금지</td><td></td><td>테이블 안 컬럼을 따로 고르지 못하게 합니다. 켜져 있으면 상태 표시줄에 작게 보입니다.</td></tr><tr><td>보기 › 패널 ▸</td><td></td><td>팔레트, 오른쪽 패널 (아웃라인), 아래 패널 (문제 목록), 캔버스 최대화.</td></tr><tr><td>보기 › 시작 화면</td><td></td><td>문서를 연 채로 시작 화면을 봅니다.</td></tr></tbody></table><h2 id="확대·이동" tabindex="-1">확대·이동 <a class="header-anchor" href="#확대·이동" aria-label="Permalink to &quot;확대·이동&quot;">​</a></h2><ul><li><strong>확대·축소</strong> — <kbd>Ctrl</kbd>+마우스 휠(마우스 위치 기준), <kbd>Ctrl</kbd>+<kbd>=</kbd> · <kbd>Ctrl</kbd>+<kbd>-</kbd> · <kbd>Ctrl</kbd>+<kbd>0</kbd>, 도구 모음의 배율 목록.</li><li><strong>화면 이동</strong> — <kbd>Space</kbd>를 누른 채 끌기(놓으면 원래 도구로), 손 도구(<kbd>H</kbd>), 마우스 가운데 버튼 끌기, 터치패드 두 손가락 스크롤, 축소 미리보기의 사각형 끌기. 글을 치는 중에는 <kbd>Space</kbd>가 글자로 들어갑니다.</li><li>배율이 40%보다 작으면 노드를 이름만 있는 간단한 상자로 그리고, 카테고리 이름을 크게 띄워 지도처럼 보이게 합니다. 이미지 내보내기·인쇄는 늘 원래 모양입니다.</li><li>배율과 보던 위치는 문서에 저장됩니다.</li></ul><h2 id="패널과-시작-화면" tabindex="-1">패널과 시작 화면 <a class="header-anchor" href="#패널과-시작-화면" aria-label="Permalink to &quot;패널과 시작 화면&quot;">​</a></h2><ul><li><strong>오른쪽 패널</strong>(아웃라인·축소 미리보기)은 <kbd>Ctrl</kbd>+<kbd>Alt</kbd>+<kbd>B</kbd>, <strong>아래 패널</strong>(문제 목록)은 <kbd>Ctrl</kbd>+<kbd>J</kbd>로 접고 폅니다. 문서 탭 줄 오른쪽 끝의 단추 둘과 보기 › 패널 ▸도 같습니다.</li><li><strong>캔버스 최대화</strong> — 문서 탭을 더블클릭하거나 <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>M</kbd>을 누르면 두 패널을 한 번에 접고, 다시 하면 접기 전으로 돌아갑니다. 팔레트는 접지 않습니다.</li><li>접은 상태는 다음에 켜도 그대로입니다.</li><li><strong>시작 화면</strong> — 보기 › 시작 화면을 고르면 새로 만들기·열기·샘플·최근 파일이 있는 시작 화면이 나옵니다. 열린 문서는 닫히지 않고, 탭을 누르거나 <kbd>Esc</kbd> 또는 <strong>열린 문서로 돌아가기</strong>로 돌아갑니다. 시작 화면을 보는 동안은 문서 메뉴와 편집 단축키가 꺼집니다.</li></ul><h2 id="아웃라인" tabindex="-1">아웃라인 <a class="header-anchor" href="#아웃라인" aria-label="Permalink to &quot;아웃라인&quot;">​</a></h2><ul><li>맨 위 <strong>이름으로 찾기</strong> 칸에 치면 목록을 걸러 봅니다.</li><li>테이블·뷰를 누르면 그 아래로 컬럼(그룹 컬럼은 그룹 이름 한 줄)과, 테이블이면 인덱스가 펼쳐집니다.</li><li>항목을 더블클릭하면 그 정보 창이 열립니다: 단어 → 단어 정보, 그룹 → 그룹 관리, 인덱스·시퀀스·트리거·테이블스페이스 → 각 정보 창, 테이블·뷰 → 캔버스에서 그 노드로 가서 선택하고 테이블(뷰) 정보 창을 엶, 컬럼 → 그 컬럼을 선택한 채 테이블 정보 창을 엶.</li><li>단어·그룹은 캔버스의 테이블에 끌어다 놓아 컬럼으로 넣을 수 있습니다.</li><li>테이블·뷰 항목 끝에 캔버스 머리와 같은 설계 검사 표시(오류 ●·경고 ▲·참고 i)가 보입니다 — 그 테이블과 컬럼들의 지적 중 가장 높은 심각도입니다. 표시에 마우스를 올리면 지적 내용(최대 5개, 넘으면 &quot;그 밖 n개&quot;)이 나오고, 표시를 눌러도 항목을 누른 것과 같습니다. 보기 › <strong>설계 검사 표시</strong>를 따르고, 참고는 <strong>참고도 캔버스에 표시</strong>를 켰을 때만, 예외로 숨긴 지적은 빠지며, 컬럼 줄에는 표시가 없습니다. <a href="/relio/features/check">설계 검사</a></li><li>오른쪽 클릭: 삭제, 그룹 관리, 트리거 추가 · 시퀀스 추가 · 인덱스 추가 · 테이블스페이스 추가(고른 종류에 맞는 것만), <strong>개요 보기 모드</strong>(논리명 · 물리명 · 논리명+물리명), <strong>정렬 기준</strong>(논리명 · 물리명).</li><li>개수가 0인 줄은 흐리게 보이고 <strong>+ 추가</strong>로 첫 항목을 바로 만듭니다. 시퀀스·테이블스페이스는 그 DB(버전)가 지원할 때만 추가할 수 있습니다.</li></ul><figure class="shot" data-scene="canvas-outline-marks"><img src="'+i+'" alt="아웃라인 테이블 항목 끝의 설계 검사 표시 — 오류 ●(예약어 이름)와 경고 ▲(논리명 중복)" loading="lazy"><figcaption>아웃라인 테이블 항목 끝의 설계 검사 표시 — 오류 ●(예약어 이름)와 경고 ▲(논리명 중복)</figcaption></figure>',43)])])}const q=d(b,[["render",n]]);export{f as __pageData,q as default};
